fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    result.extend_from_slice(v1);
    result.extend_from_slice(v2);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    if first.is_empty() {
        // According to problem statement, first is non-empty.
        // But to be safe, if empty, just return second.clone().
        return second.clone();
    }
    let len_first_minus_one = first.len() - 1;
    // Take all elements of first except the last
    let mut result = Vec::with_capacity(len_first_minus_one + second.len());
    result.extend_from_slice(&first[..len_first_minus_one]);
    result.extend_from_slice(second);
    result
}